-- Dán toàn bộ file này vào Supabase → SQL Editor → Run. Chạy lại nhiều lần vẫn an toàn.
-- Sinh từ data/*.json; tương đương npm run db:setup.

-- ============================================================
-- BinGo · PostgreSQL schema
-- Chạy bằng: npm run db:setup  (tạo bảng + nạp dữ liệu mẫu từ data/*.json)
-- ============================================================

CREATE TABLE IF NOT EXISTS trash_bins (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    latitude    DOUBLE PRECISION NOT NULL CHECK (latitude BETWEEN -90 AND 90),
    longitude   DOUBLE PRECISION NOT NULL CHECK (longitude BETWEEN -180 AND 180),
    district    TEXT NOT NULL,
    type        TEXT NOT NULL,
    status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'full', 'broken')),
    recyclable  BOOLEAN NOT NULL DEFAULT FALSE,
    address     TEXT NOT NULL DEFAULT '',
    updated_on  DATE NOT NULL DEFAULT CURRENT_DATE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS trash_bins_district_idx ON trash_bins (district);
CREATE INDEX IF NOT EXISTS trash_bins_status_idx ON trash_bins (status);

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, district = EXCLUDED.district, type = EXCLUDED.type, status = EXCLUDED.status, recyclable = EXCLUDED.recyclable, address = EXCLUDED.address, updated_on = EXCLUDED.updated_on;

-- Backend truy cập bằng chuỗi kết nối Postgres (không qua API Supabase), nên bật RLS để chặn truy cập công khai qua anon key.
ALTER TABLE trash_bins ENABLE ROW LEVEL SECURITY;

-- Tài khoản người dùng (đăng ký email + đăng nhập Google)
CREATE TABLE IF NOT EXISTS users (
    id             TEXT PRIMARY KEY,
    email          TEXT NOT NULL UNIQUE,
    password_hash  TEXT,
    google_id      TEXT UNIQUE,
    name           TEXT NOT NULL DEFAULT '',
    role           TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
    created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (password_hash IS NOT NULL OR google_id IS NOT NULL)
);

-- Nâng cấp DB đã có bảng users từ trước
ALTER TABLE users ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin'));
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
